int configure_usb_console(struct console *co, char *options) {
    struct usb_serial_port *port;
    struct termios tty;
    int baud, data_bits, flow_ctl;
    char parity;
    int ret = 0;

    if (options == NULL || co == NULL) {
        return -EINVAL;
    }

    /* Parse options string */
    if (sscanf(options, "%d %c %d %d", &baud, &parity, &data_bits, &flow_ctl) != 4) {
        return -EINVAL;
    }

    port = get_usb_serial_port(co->index);
    if (!port) {
        log_error("Failed to retrieve USB serial port for console index %d", co->index);
        return -ENODEV;
    }

    if (!port_is_connected(port)) {
        log_error("USB port for console index %d is not connected", co->index);
        return -ENODEV;
    }

    if (open_usb_port(port) < 0) {
        log_error("Failed to open USB port for console index %d", co->index);
        return -EIO;
    }

    memset(&tty, 0, sizeof/tty);
    tty.c_cflag = CREAD | CLOCAL;

    switch (baud) {
        case 9600:
            cfsetispeed(&tty, B9600);
            cfsetospeed(&tty, B9600);
            break;
        case 115200:
            cfsetispeed(&tty, B115200);
            cfsetospeed(&tty, B115200);
            break;
        default:
            ret = -EINVAL;
            goto error;
    }

    switch (parity) {
        case 'n':
        case 'N':
            tty.c_cflag &= ~PARENB;
            break;
        case 'o':
        case 'O':
            tty.c_cflag |= PARENB | PARODD;
            break;
        case 'e':
        case 'E':
            tty.c_cflag |= PARENB;
            tty.c_cflag &= ~PARODD;
            break;
        default:
            ret = -EINVAL;
            goto error;
    }

    switch (data_bits) {
        case 7:
            tty.c_cflag &= ~CSIZE;
            tty.c_cflag |= CS7;
            break;
        case 8:
            tty.c_cflag &= ~CSIZE;
            tty.c_cflag |= CS8;
            break;
        default:
            ret = -EINVAL;
            goto error;
    }

    if (flow_ctl == 1) {
        tty.c_cflag |= CRTSCTS;
    } else {
        tty.c_cflag &= ~CRTSCTS;
    }

    if (tcsetattr(port->fd, TCSANOW, &tty) < 0) {
        ret = -EIO;
        goto error;
    }

    co->is_console = 1;

    return 0;

error:
    close_usb_port(port);
    return ret;
}

int configure_usb_console(struct console *co, char *options) {
    int baud = 0, bits = 0;
    char parity = '\0';
    int flow_control = 0;
    char *token;

    token = strtok(options, ",");
    while (token != NULL) {
        if (strncmp(token, "baud=", 5) == 0) {
            baud = atoi(token + 5);
        } else if (strncmp(token, "bits=", 5) == 0) {
            bits = atoi(token + 5);
        } else if (strncmp(token, "parity=", 7) == 0) {
            parity = token[7];
        } else if (strncmp(token, "flow=", 5) == 0) {
            flow_control = (strncmp(token + 5, "rtscts", 6) == 0) ? 1 : 0;
        }
        token = strtok(NULL, ",");
    }

    struct usb_serial_port *port = get_usb_serial_port(co->index);
    if (!port) {
        log_error("Failed to retrieve USB serial port for console index %d", co->index);
        return -1;
    }

    if (!port_is_connected(port)) {
        log_error("USB serial port is not connected for console index %d", co->index);
        return -1;
    }

    if (open_usb_serial_port(port) < 0) {
        log_error("Failed to open USB serial port for console index %d", co->index);
        return -1;
    }

    if (configure_terminal(port, baud, bits, parity, flow_control) < 0) {
        close_usb_serial_port(port);
        log_error("Failed to configure terminal for USB serial port of console index %d", co->index);
        return -1;
    }

    co->is_configured = 1;
    co->port = port;
    port->is_console = 1;

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

// Assuming these structures and functions exist in the codebase
struct console {
    int index;
    int is_system_console;
};

struct usb_serial {
    int is_connected;
    int baud_rate;
    int data_bits;
    char parity;
    int flow_control;
};

struct usb_serial *get_usb_serial_port(int index);

int configure_usb_console(struct console *co, char *options) {
    struct usb_serial *port;
    char *token;
    int baud_rate = 0;
    int data_bits = 0;
    char parity = '\0';
    int flow_control = 0;
    int ret = 0;

    // Parse the options string
    token = strtok(options, ",");
    while (token != NULL) {
        if (strncmp(token, "baud=", 5) == 0) {
            baud_rate = atoi(token + 5);
        } else if (strncmp(token, "bits=", 5) == 0) {
            data_bits = atoi(token + 5);
        } else if (strncmp(token, "parity=", 7) == 0) {
            parity = token[7];
        } else if (strncmp(token, "flowctrl=", 9) == 0) {
            flow_control = atoi(token + 9);
        }
        token = strtok(NULL, ",");
    }

    // Get the USB serial port
    port = get_usb_serial_port(co->index);
    if (!port) {
        perror("Failed to get USB serial port");
        return -1;
    }

    // Check if the port is connected
    if (!port->is_connected) {
        fprintf(stderr, "USB serial port not connected\n");
        return -ENOENT;
    }

    // Configure the port settings
    port->baud_rate = baud_rate;
    port->data_bits = data_bits;
    port->parity = parity;
    port->flow_control = flow_control;

    // Mark the port as system console
    co->is_system_console = 1;

    return ret;
}

int usb_console_configure(struct console *co, char *options) {
    int baud_rate = 0;
    int data_bits = 0;
    int parity = 0;
    int flow_control = 0;
    char *token;

    token = strtok(options, ",");
    while (token != NULL) {
        if (strncmp(token, "baud", 4) == 0) {
            baud_rate = atoi(token + 4);
        } else if (strncmp(token, "bits", 4) == 0) {
            data_bits = atoi(token + 4);
        } else if (strncmp(token, "parity", 6) == 0) {
            parity = atoi(token + 6);
        } else if (strncmp(token, "flow", 4) == 0) {
            flow_control = atoi(token + 4);
        }
        token = strtok(NULL, ",");
    }

    struct usb_serial_port *port = usb_serial_get_port(co->index);
    if (!port) {
        printk(KERN_ERR "Failed to retrieve USB serial port for console index %d\n", co->index);
        return -ENODEV;
    }

    if (!usb_serial_port_is_connected(port)) {
        printk(KERN_ERR "USB serial port is not connected\n");
        return -ENODEV;
    }

    if (usb_serial_open_port(port)) {
        printk(KERN_ERR "Failed to open USB serial port\n");
        return -EIO;
    }

    struct termios tio;
    tio.c_cflag = baud_rate | data_bits | parity | flow_control | CLOCAL | CREAD;
    tio.c_iflag = 0;
    tio.c_oflag = 0;
    tio.c_lflag = 0;

    if (usb_serial_set_termios(port, &tio)) {
        printk(KERN_ERR "Failed to configure terminal settings\n");
        usb_serial_close_port(port);
        return -EIO;
    }

    co->port = port;
    port->is_console = 1;

    return 0;
}

int configure_usb_console(struct console *co, char *options) {
    int baud_rate = 115200;
    int data_bits = 8;
    int parity = 0;
    int flow_control = 0;
    char *token;

    token = strtok(options, ",");
    while (token != NULL) {
        if (strncmp(token, "baud=", 5) == 0) {
            baud_rate = atoi(token + 5);
        } else if (strncmp(token, "bits=", 5) == 0) {
            data_bits = atoi(token + 5);
        } else if (strncmp(token, "parity=", 7) == 0) {
            if (strcmp(token + 7, "odd") == 0)
                parity = PARENB | PARODD;
            else if (strcmp(token + 7, "even") == 0)
                parity = PARENB;
            else
                parity = 0;
        } else if (strncmp(token, "flow=", 5) == 0) {
            if (strcmp(token + 5, "rtscts") == 0)
                flow_control = CRTSCTS;
            else
                flow_control = 0;
        }
        token = strtok(NULL, ",");
    }

    struct usb_serial_port *port = get_usb_serial_port_by_index(co->index);
    if (!port) {
        pr_err("Failed to get USB serial port for console index %d\n", co->index);
        return -ENODEV;
    }

    if (!port->connected) {
        pr_err("USB serial port for console index %d is not connected\n", co->index);
        return -ENODEV;
    }

    struct tty_struct *tty = tty_port_alloc(port);
    if (!tty) {
        pr_err("Failed to allocate TTY for USB console\n");
        return -ENOMEM;
    }

    if (tty_port_open(port, tty, NULL) < 0) {
        pr_err("Failed to open USB serial port\n");
        kfree(tty);
        return -EIO;
    }

    struct ktermios termios;
    memset(&termios, 0, sizeof(termios));
    termios.c_cflag = CLOCAL | CREAD | CS8;
    termios.c_cflag &= ~CSTOPB;
    termios.c_cflag |= flow_control;
    termios.c_cflag &= ~PARENB;
    termios.c_cflag |= parity;
    termios.c_cflag &= ~CSIZE;
    termios.c_cflag |= data_bits;
    termios.c_ispeed = baud_rate;
    termios.c_ospeed = baud_rate;

    tty_set_termios(tty, &termios);
    co->tty = tty;
    co->is_system_console = 1;

    return 0;
}
